import { useEffect } from 'react';
import { registry } from '../session/registry';
import { SessionView } from './SessionView';
import { PaneSkeleton } from './PaneSkeleton';

export function PaneHost({ pane }) {
  const session = useSession(pane.sessionId);
  useEffect(() => {
    const handle = registry.attach(pane.sessionId);
    return () => handle.detach();
  }, [pane.sessionId]);
  if (!session) return <PaneSkeleton />;
  return <SessionView session={session} />;
}

function onClose() {
  layout.hide(pane.id); // restorable
}

export type LayoutNode = SplitNode | LeafNode;

export interface SplitNode {
  type: 'split';
  direction: 'row' | 'column';
  ratio: number;
  first: LayoutNode;
  second: LayoutNode;
}

export interface LeafNode {
  type: 'leaf';
  id: string;
  viewId: string | null;
}

// A leaf holds a view id and nothing else: the layout never learns which
// kind of resource it is arranging.
export function leaves(node: LayoutNode): LeafNode[] {
  return node.type === 'leaf' ? [node] : [...leaves(node.first), ...leaves(node.second)];
}

export interface Pty {
  write(data: string): void;
  resize(cols: number, rows: number): void;
  kill(): void;
}

export function spawnPty(cwd: string): Pty {
  throw new Error('The native PTY service is not implemented yet.');
}

import { spawnPty, type Pty } from '../pty/spawn';

type Handle = { id: string; detach(): void };
const sessions = new Map<string, Session>();

export function attach(id: string): Handle {
  const s = sessions.get(id) ?? create(id);
  s.refs += 1;
  return { id, detach: () => release(s) };
}

function release(s: Session) {
  s.refs -= 1;
  if (s.refs > 0) return;
  // nobody is looking — keep the PTY alive,
  // but start the idle clock
  s.idleSince = Date.now();
}

export function restore(id: string) {
  const s = sessions.get(id);
  if (!s) return null;
  return { scrollback: s.buffer.snapshot() };
}

import { describe, expect, it } from 'vitest';
import { attach, restore } from './registry';

describe('registry', () => {
  it('detach keeps the process alive', () => {
    const handle = attach('session-1');
    handle.detach();
    expect(restore('session-1')).not.toBeNull();
  });

  it('reattach replays scrollback', () => {
    attach('session-2').detach();
    expect(restore('session-2')?.scrollback).toBeDefined();
  });
});

